def clean(df):
    d = df.copy()
    # drop exact duplicate rows
    d = d.drop_duplicates().reset_index(drop=True)
    # fix island label variants (extra spaces / typos)
    d['island'] = d['island'].astype(str).str.strip()
    island_map = {'Bisco': 'Biscoe', 'Torgerson': 'Torgersen'}
    d['island'] = d['island'].replace(island_map)
    # fix sex label variants
    d['sex'] = d['sex'].astype(str).str.strip().str.lower().replace({'nan': None})
    # numeric columns stored as text (commas, etc.)
    for col in ['body_mass_g', 'flipper_length_mm']:
        if col in d.columns:
            d[col] = pd.to_numeric(
                d[col].astype(str).str.replace(',', '', regex=False).str.strip(),
                errors='coerce'
            )
    return d

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['island'])
    counts = d.groupby('island').size()
    return {str(k): int(v) for k, v in counts.items()}
